  hurt: [3, [80, 40, 120]], od: [3, [30, 40, 30, 40, 40, 50, 110]], boss: [3, [50, 50, 150]], win: [3, [40, 80, 40, 80, 120]], tele: [2, [10, 30, 10]],
  // every weapon's swing has its own feel in the hand
