        off = u < .42 ? d * (-1.6 + 2.6 * eo(u / .42)) : d * (1.0 - .4 * eo(seg(u, .42, .8))); o.r = u < .42 ? 1 : fr < 1 ? 1 - .2 * Math.sin(Math.PI * fr) : 1;
