    if (s.w === 'chakram' && u >= .15 && !(s.ev & 1)) { s.ev |= 1; if (!quiet) Aud.wbeat('chakram', 0); }
    if ((s.w === 'katana' || s.w === 'muramasa') && u >= .3 && !(s.ev & 1)) { s.ev |= 1; if (!quiet) Aud.wbeat(s.w, 0); }
