    cx.fillStyle = '#4a5478'; cx.fillRect(c * 2 - 3, s * 2 - 3, 6, 6); cx.strokeStyle = '#2a3150'; cx.lineWidth = 7; cx.beginPath(); cx.moveTo(c * 1, s * 1); cx.lineTo(c * r0, s * r0); cx.stroke();
