    G.twBoss = 0; P.fangN = P.thN = 0; P.phx = 0; this.rc0 = P.rc; this.mineT = 0;
    G.twEv = REPLAY.on ? (REPLAY.hdr.tev || '') : FChal.cur && FChal.cur.m === 'tower' ? FChal.cur.ev : (towerData().ev ? towerEvent().id : '');
