    if (REPLAY.on) { G.nem = REPLAY.hdr.nem || null; return; }
    const n = Store.data.nem, ok = NEM_MODES[mode] && !(mode === 'story' && (!stage || stage.safe || stage.obj.t === 'boss' || stage.obj.t === 'courier' || stage.ch < 1));
