  for (let i = 0; i < 14; i++) { const x = (i * 97.3 + CAM.t * 30) % V.VW, y = (i * 211.7 + CAM.t * 1400) % (V.VH + 200) - 100; cx.moveTo(x, y); cx.lineTo(x, y + 60); }
  cx.stroke(); cx.globalAlpha = 1;
