  if (LOCK_LANG !== LANG.id) { LOCK_LANG = LANG.id; for (let i = 0; i < 5; i++) LOCK_TXT[i] = ltf('LOCK {0}', i + 1); }
  const dx = In.cx - In.sx, dy = In.cy - In.sy; if (dx * dx + dy * dy < 130) return;
