  cx.fillStyle = '#000'; cx.globalAlpha = .96;
  cx.fillRect(-M, -M, V.VW + M * 2, y + M); cx.fillRect(-M, y + r * 2, V.VW + M * 2, V.VH + M); cx.fillRect(-M, y, x + M, r * 2); cx.fillRect(x + r * 2, y, V.VW + M, r * 2);
