    if (this.hp >= 0 && hp < this.hp) for (let i = hp; i < this.hp && i < mx; i++) this.shards.push({ x: x0 + 7 + i * 17, y: 68, t: 0, c: this.hp === 2 ? '#00ff88' : i === 0 ? '#ff3b5c' : '#00ff88' });
