    cx.fillStyle = '#ff9a3d'; cx.beginPath(); cx.ellipse(0, 0, 7, 4, 0, 0, TAU); cx.fill(); cx.beginPath(); cx.arc(7, -2, 3.6, 0, TAU); cx.fill();
