    const mine = b.lastHp - b.hp; if (mine > 0) { this.dmgOut += mine; this.myDmg += mine; }
    if (this.dmgIn > 0 && b.dying <= 0) { b.hp = Math.max(1, b.hp - this.dmgIn); this.dmgIn = 0; b.fl = Math.max(b.fl, .4); }
