      w.forEach((e, i) => { const t = ENAME2T[e[0]]; if (t == null) return; let x = L + e[1] * W, y = top + e[2] * H; if (dist(x, y, P.x, P.y) < 90) y = P.y > V.VH * .5 ? top : V.VH - 160; D.q.push({ t: .25 + i * .12, type: t, x, y, el: e[3] ? 1 : 0 }); });
