  list() { return ['pre: ' + this.pre.map(h => h.order + ' ' + h.name + (h.off ? ' (off)' : '')).join(', '), 'post: ' + this.post.map(h => h.order + ' ' + h.name + (h.off ? ' (off)' : '')).join(', ')]; }
