    cx.save(); cx.globalAlpha = .38 * e.vis; cx.fillStyle = '#000'; cx.beginPath(); cx.ellipse(e.x + r * .25, e.y + r * .55, r * 1.05, r * .45, 0, 0, TAU); cx.fill(); cx.restore();
