    P0(new T.CylinderGeometry(.9, .9, 5, 8), M.dark, -1, 0, 0, blade).geometry.rotateZ(Math.PI / 2);
    P0(new T.BoxGeometry(1.2, 5, 1.6), M.gold, 1.6, 0, 0, blade);
