    const bg = R3.ent('boss' + b.id + (b.lvl || ''), () => R3.bossModel(b)); if (!bg || !bg.mon) return; const r = bg.mon, now = performance.now() / 1000, dt = Math.min(.05, Math.max(0, now - (r.t || now))); r.t = now;
