    if (r.hurtT > 0) r.hurtT -= dt; else { r.hurtT = 0; Models.play(r, slam ? 'Punch' : b.stag > 0 ? 'HitReact' : 'Idle', .15, slam); }
    if (r.cur === 'Punch' && r.acts.Punch && !r.acts.Punch.isRunning()) r.cur = ''; r.mixer.update(dt);
